// Script for Automation: Update a record and write the result to a log field.
// Version 3: Added "in progress" status update.

// 1. Get the record from the automation trigger
const inputConfig = input.config();
const recordId = inputConfig.recordId;
const table = base.getTable('Projecten');

// Define Field IDs for easy reference and maintenance
const projectDocAssetsFieldId = "fldzUsDJoFrUJgYBH";
const projectDocUrlFieldId = "fldPyhxENAMgCd5lG";
const createProjectPlanFieldId = "fldZcibinoCxFDD9Q";
const scriptLogFieldId = "fld0IowHqbNeloFqs";


// We need to fetch the record to read its values.
// Using field IDs in the 'fields' array is more reliable than using names.
const record = await table.selectRecordsAsync({ 
    recordIds: [recordId], 
    fields: [projectDocAssetsFieldId, projectDocUrlFieldId] 
}).then(result => result.records[0]);

// 2. Main Logic: Proceed only if a record was found
if (record) {
    // Immediately update the log to show the script is running.
    await table.updateRecordAsync(record.id, {
        [scriptLogFieldId]: '⏳ Creating project plan...'
    });

    // Read the values from the fields using their IDs
    const projectDocAssets = record.getCellValue(projectDocAssetsFieldId);
    const projectDocUrl = record.getCellValue(projectDocUrlFieldId);

    // Check for empty values
    const isAssetsEmpty = !projectDocAssets || projectDocAssets.length === 0;
    const isUrlEmpty = !projectDocUrl;

    // 3. Conditional Update & Logging
    if (isAssetsEmpty && isUrlEmpty) {
        // If both fields are empty, update the checkbox and the log field using their IDs.
        await table.updateRecordAsync(record.id, {
            [createProjectPlanFieldId]: true,
            [scriptLogFieldId]: '✅ Project plan creation in progress.'
        });
    } else {
        // If a document exists, update the log field with an informational message.
        await table.updateRecordAsync(record.id, {
            [scriptLogFieldId]: '⚠️ No action taken: A project document already exists.'
        });
    }
} else {
    // This error will only appear in the automation run history.
    console.error('Error: Record not found.');
}
